var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type={personInfo.Type.Name}, Props={personInfo.Properties.Count}");

string json = JsonSerializer.Serialize(new Person("Ada", 38), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): check-without-throwing ---

// 2a. Type the resolver *can* handle (default reflection resolver handles any type)
if (options.TryGetTypeInfo<Person>(out var info))
    Console.WriteLine($"TryGet Person  → found ({info!.Type.Name})");
else
    Console.WriteLine("TryGet Person  → not available");

// 2b. Use a source-gen context that only knows about Person — int will NOT resolve.
var limited = new JsonSerializerOptions { TypeInfoResolver = SmallContext.Default };

if (limited.TryGetTypeInfo<int>(out var intInfo))
    Console.WriteLine($"TryGet int     → found ({intInfo!.Type.Name})");
else
    Console.WriteLine("TryGet int     → not available (resolver doesn't know this type)");

// -- types / source-gen context ------------------------------------------------
public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class SmallContext : JsonSerializerContext;

